'use strict';
// Q&A-only product: old browser records are retained, but social/chat/lesson UI is not loaded.
state.profile=state.profile||{name:'JV Ursal',department:'',rank:'',experience:'',country:'',bio:'',photo:''};state.qaBadges=state.qaBadges||{};state.qaVisits=state.qaVisits||[];state.reports=state.reports||[];state.followed=state.followed||[];
const topicsByDepartment={Engine:['Purifier','Main Engine','Auxiliary Engine / Generator','Fresh Water Generator','Air Compressor','Boiler','Pumps','Refrigeration & AC'],Deck:['Cargo Operations','Mooring & Anchoring','Deck Machinery','Navigation & Bridge'],Electrical:['Electrical','Automation & Controls'],General:['Safety & Work Procedures','Career & Certificates','Life at Sea']};
equipment.splice(0,equipment.length,'All topics',...Object.values(topicsByDepartment).flat());
const departmentFor=t=>Object.keys(topicsByDepartment).find(d=>topicsByDepartment[d].includes(t));
let own=q=>q.author==='JV Ursal'||q.owner==='local-user';
let ownAnswer=a=>a.name==='JV Ursal'||a.owner==='local-user';
const qProfileName=()=>state.profile.name?.trim()||'JV Ursal';
const topicSymbol=t=>({Engine:'⚙',Deck:'⚓',Electrical:'ϟ',General:'◎'})[departmentFor(t)]||'◎';
function activityMetrics(){const list=all();const mine=list.filter(own);const contributed=list.filter(q=>!own(q)&&q.answers.some(ownAnswer));const counts={};for(const q of contributed)counts[q.equipment]=(counts[q.equipment]||0)+1;return{asked:mine.length,answered:contributed.length,outcomes:mine.filter(q=>q.status==='Resolved'&&q.outcome?.trim()).length,saved:new Set(state.saved).size,topics:Object.entries(counts).sort((a,b)=>b[1]-a[1]),mine,contributed}}
const qaBadgeDefinitions=[{id:'starter',title:'Starter',symbol:'⚓',rule:'Complete your name, department, and rank in Profile.',check:()=>!!(state.profile.name?.trim()&&state.profile.department&&state.profile.rank?.trim())},{id:'question',title:'First Question',symbol:'?',rule:'Post your first structured question.',check:()=>activityMetrics().asked>0},{id:'contributor',title:'Contributor',symbol:'↗',rule:'Answer a question asked by another seafarer.',check:()=>activityMetrics().answered>0},{id:'conversation',title:'Conversation Starter',symbol:'☷',rule:'Receive an answer from another person on your question.',check:()=>all().some(q=>own(q)&&q.answers.some(a=>!ownAnswer(a)))},{id:'loop',title:'Loop Closer',symbol:'✓',rule:'Return to your question and record a reported outcome.',check:()=>activityMetrics().outcomes>0},{id:'keeper',title:'Knowledge Keeper',symbol:'▤',rule:'Save three different questions for later.',check:()=>new Set(state.saved).size>=3}];
function awardQABadges(){const earned=[];for(const b of qaBadgeDefinitions)if(!state.qaBadges[b.id]&&b.check()){state.qaBadges[b.id]=new Date().toISOString();earned.push(b)}return earned}
const basePersist=persist;let badgeNoticeTimer;
persist=function(){const before={...state.qaBadges};const fresh=awardQABadges();if(!basePersist()){state.qaBadges=before;return false}if(fresh.length){document.querySelector('#qaNotice')?.remove();const n=document.createElement('div');n.className='qa-notice';n.id='qaNotice';n.setAttribute('role','status');n.innerHTML=`<button aria-label="Dismiss milestone">×</button><span class="eyebrow">MILESTONE UNLOCKED · LOCAL PREVIEW</span><strong>${fresh.at(-1).symbol} ${fresh.at(-1).title}</strong>Find your milestones in Profile.`;document.body.appendChild(n);n.querySelector('button').onclick=()=>n.remove();clearTimeout(badgeNoticeTimer);badgeNoticeTimer=setTimeout(()=>n.remove(),6500)}return true};
let qaDepartment='All departments',qaView='all',lastViewedId=null;
const baseQuestionCard=card,baseDetail=detail,baseAsk=ask;
card=function(q){if(own(q))return baseQuestionCard({...q,author:qProfileName()});return baseQuestionCard(q)};
nav=function(p){page=['home','explore','ask','learn','profile','badges'].includes(p)?p:'home';selected=null;qaView='all';if(page==='explore'||page==='learn'){topic='All topics';query='';sort='recent';qaDepartment='All departments'}render();window.scrollTo(0,0)};
renderNav=function(){const items=[['home','home','Dashboard'],['explore','explore','Questions'],['ask','ask','Ask'],['learn','learn','Library'],['profile','profile','Profile']];for(const id of ['desktopNav','mobileNav'])document.getElementById(id).innerHTML=items.map(([p,i,label])=>`<button data-nav="${p}" class="${page===p||p==='profile'&&page==='badges'?'active':''}">${icon(i)}<span>${label}</span></button>`).join('');const user=document.querySelector('.sidebar .user');if(user)user.innerHTML=`${state.profile.photo?`<img class="qa-photo-slot" src="${esc(state.profile.photo)}" alt="Your profile photo">`:'<div class="avatar">'+esc(qProfileName().slice(0,2).toUpperCase())+'</div>'}<div><b>${esc(qProfileName())}</b><small>Local prototype profile</small></div>`};
function dashboard(){const m=activityMetrics();const earned=qaBadgeDefinitions.filter(b=>state.qaBadges[b.id]).sort((a,b)=>state.qaBadges[b.id].localeCompare(state.qaBadges[a.id]));const newest=earned[0];const fav=state.followed.filter(t=>equipment.includes(t));const recently=[...new Set([...state.qaVisits].reverse().map(v=>v.topic))].slice(0,4);const unanswered=all().filter(q=>!q.answers.length);const suggested=unanswered.filter(q=>fav.includes(q.equipment)).slice(0,2);const needs=suggested.length?suggested:unanswered.slice(0,2);app.innerHTML=`<div class="qa-head"><div><div class="qa-greeting">WELCOME BACK, ${esc(qProfileName().split(' ')[0].toUpperCase())}</div><h1>Your experience matters.</h1><p>Ask clearly. Share what you know. Keep the answer within reach.</p></div><button class="btn" data-nav="ask">${icon('ask')} Ask</button></div><section class="qa-hero"><div class="hero-text"><div class="medal">${newest?.symbol||'⚓'}</div><div class="eyebrow">${newest?'YOUR LATEST MILESTONE':'YOUR NEXT MILESTONE'}</div><h2>${newest?newest.title:'Start your journey.'}</h2><p>${newest?newest.rule:'Complete your profile to earn Starter. Your department and experience help add context to your contributions.'}</p><button class="btn gold" data-nav="${newest?'badges':'profile'}">${newest?'Your milestones so far':'Complete your profile'} →</button></div><img class="mascot" src="assets/seafarer-mascot.webp" width="500" height="465" alt="Bulletproof Seafarers mascot giving a thumbs-up"></section><form id="qaQuickSearch" class="search">${icon('search')}<input name="search" required type="search" aria-label="Find a previous answer" placeholder="Search the problem before asking the crew…"><button class="qa-link" type="submit">Search →</button></form><div class="qa-metrics">${[['asked',m.asked,'Questions you asked'],['answered',m.answered,'Questions you answered'],['outcomes',m.outcomes,'Outcomes you recorded'],['saved',m.saved,'Saved for later']].map(([v,n,label])=>`<button class="qa-metric" data-activity="${v}"><strong>${n}</strong><span>${label}</span></button>`).join('')}</div><div class="qa-grid"><div><section class="qa-section"><div class="section-heading"><h2>Your favorite topics</h2><button class="qa-link" data-nav="profile">Manage →</button></div>${fav.length?`<div class="topic-grid">${fav.slice(0,6).map(t=>topicTile(t)).join('')}</div>`:'<div class="card qa-empty">Choose favorite topics in Profile to make this dashboard yours.</div>'}</section><section class="qa-section"><div class="section-heading"><h2>Could your experience help?</h2><button class="qa-link" data-activity="unanswered">Unanswered →</button></div>${needs.map(card).join('')||'<div class="card qa-empty">No unanswered questions in the current library.</div>'}</section><section class="qa-section"><div class="section-heading"><h2>Recently explored topics</h2></div>${recently.length?`<div class="chips">${recently.map(t=>`<button class="chip" data-qa-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div>`:'<p class="qa-empty">Open a question and the topics you explore will appear here.</p>'}</section></div><aside class="qa-side"><div class="card"><h3>Where you’ve contributed</h3>${m.topics.length?m.topics.slice(0,4).map(([t,n])=>`<div class="topic-rank"><button class="qa-link" data-qa-topic="${esc(t)}">${esc(t)}</button><small>${n} question${n===1?'':'s'} answered</small></div>`).join(''):'<p>Your most-answered topics will appear after you contribute. We count different questions, not repeated replies.</p>'}</div><div class="qa-helper"><strong>Every question adds to the Library.</strong><p>Search first. Ask with context. Return with what happened. That last update helps the next seafarer.</p><button class="qa-link" data-nav="learn">Explore the Library →</button></div><div class="card"><h3>Across departments</h3>${Object.entries(topicsByDepartment).map(([d,topics])=>`<div class="topic-rank"><button class="qa-link" data-qa-dept="${d}">${d==='General'?'General shipboard':d}</button><small>${all().filter(q=>q.dept===d).length} sample / local cases</small></div>`).join('')}</div><p class="qa-support">Prototype activity includes your browser-local tests. Sample discussions are fictional. Milestones recognize participation, not expertise or verified technical correctness.</p></aside></div>`;document.querySelector('#qaQuickSearch').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('search').trim();if(!value)return;page='learn';query=value;topic='All topics';sort='recent';qaDepartment='All departments';qaView='all';render();window.scrollTo(0,0)}}
function topicTile(t){return `<button class="topic-tile" data-qa-topic="${esc(t)}"><span class="topic-symbol">${topicSymbol(t)}</span><span class="topic-name">${esc(t)}</span><small>→</small></button>`}
filtered=function(){const alias=s=>s.toLowerCase().replace(/\bfwg\b/g,'fresh water generator').replace(/\ba\/c\b/g,'refrigeration');const words=alias(query).split(/\s+/).filter(Boolean);let list=all().filter(q=>(topic==='All topics'||q.equipment===topic)&&(qaDepartment==='All departments'||q.dept===qaDepartment)&&words.every(w=>alias(q.title+' '+q.body+' '+q.equipment+' '+q.tags.join(' ')+' '+q.answers.map(a=>a.text).join(' ')).includes(w)));if(sort==='unanswered'||qaView==='unanswered')list=list.filter(q=>!q.answers.length);if(sort==='resolved'||qaView==='outcomes')list=list.filter(q=>q.status==='Resolved'&&q.outcome);if(qaView==='asked')list=list.filter(own);if(qaView==='answered')list=list.filter(q=>!own(q)&&q.answers.some(ownAnswer));if(qaView==='saved')list=list.filter(q=>state.saved.includes(q.id));return list};
function questionLibrary(){const library=page==='learn';const activeTopics=qaDepartment==='All departments'?equipment.slice(1):topicsByDepartment[qaDepartment];app.innerHTML=`<div class="qa-head"><div><div class="qa-greeting">${library?'THE SEAFARER QUESTION & ANSWER LIBRARY':'FROM SEAFARERS, FOR SEAFARERS'}</div><h1>${library?'Someone may have asked it already.':'One question. Shared experience.'}</h1><p>${library?'Every posted question and its answers stay together, organized by topic.':'Ask the crew, add context, and return with the reported outcome.'}</p></div></div>${library?`<div class="qa-library-grid">${['All departments',...Object.keys(topicsByDepartment)].map(d=>`<button class="department ${qaDepartment===d?'active':''}" data-qa-dept="${d}"><b>${d==='General'?'General shipboard':d}</b><span>${d==='All departments'?all().length:all().filter(q=>q.dept===d).length} sample / local questions</span></button>`).join('')}</div>`:''}<label class="search">${icon('search')}<input id="search" type="search" value="${esc(query)}" aria-label="Search all questions and answers" placeholder="Search a problem, equipment, or previous answer…"></label><div class="qa-filterbar"><label>Department<select id="qaDept">${['All departments',...Object.keys(topicsByDepartment)].map(d=>`<option ${qaDepartment===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Topic<select id="qaTopic">${['All topics',...activeTopics].map(t=>`<option ${topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Show<select id="qaStatus"><option value="recent">All questions</option><option value="unanswered">Unanswered</option><option value="resolved">Reported resolved</option></select></label></div><div class="qa-page-links">${[['all','All questions'],['unanswered','Unanswered'],['asked','My questions'],['answered','My contributions'],['saved','Saved']].map(([v,label])=>`<button class="${qaView===v?'active':''}" data-qa-view="${v}">${label}</button>`).join('')}</div><div class="section-heading"><h2>${topic==='All topics'?'Questions & answers':esc(topic)}</h2><small class="qa-status" id="resultCount"></small></div><div id="results"></div><p class="qa-support">Reported resolved means the asker recorded an outcome. It does not establish that a fix applies to your equipment. Follow your vessel’s procedures, manuals, and responsible officers.</p>`;document.querySelector('#qaStatus').value=sort;results();document.querySelector('#search').oninput=e=>{query=e.target.value;results()};document.querySelector('#qaDept').onchange=e=>{qaDepartment=e.target.value;topic='All topics';questionLibrary()};document.querySelector('#qaTopic').onchange=e=>{topic=e.target.value;results()};document.querySelector('#qaStatus').onchange=e=>{sort=e.target.value;qaView='all';questionLibrary()}}
function qaBadgesView(){app.innerHTML=`<button class="back" data-nav="profile">← Profile</button><h1 class="page-title">Your milestones so far.</h1><p class="subtitle">The small contributions that build a useful seafarer library.</p><div class="qa-banner">Local participation milestones only. A badge is not a professional credential or verification that an answer is technically correct.</div><div class="badge-grid">${qaBadgeDefinitions.map(b=>`<article class="badge-card ${state.qaBadges[b.id]?'':'locked'}"><div class="medal">${b.symbol}</div><h3>${b.title}</h3><p>${b.rule}</p><small>${state.qaBadges[b.id]?'✓ Earned in this browser':'Not earned yet'}</small></article>`).join('')}</div>`}
profile=function(){const p=state.profile;const m=activityMetrics();app.innerHTML=`<div class="qa-profile-title">${p.photo?`<img class="qa-avatar" src="${esc(p.photo)}" alt="Your profile photo">`:`<div class="qa-avatar">${esc(qProfileName().slice(0,2).toUpperCase())}</div>`}<div><h1>${esc(qProfileName())}</h1><p>${esc([p.rank,p.department].filter(Boolean).join(' · ')||'Build a profile that gives context to your answers.')}</p><span class="qa-preview-tag">SELF-REPORTED · LOCAL PROTOTYPE</span></div></div><div class="profile-grid"><form id="qaProfileForm" class="card"><h2 style="font-size:17px;margin-top:0">Your seafarer profile</h2><label class="field">Display name<input name="name" required maxlength="60" value="${esc(p.name)}"></label><div class="two"><label class="field">Department<select name="department"><option value="">Choose department</option>${Object.keys(topicsByDepartment).map(d=>`<option ${p.department===d?'selected':''}>${d}</option>`).join('')}</select></label><label class="field">Rank / role<input name="rank" maxlength="70" value="${esc(p.rank)}" placeholder="e.g. Oiler, Deck Cadet, Chief Officer"></label></div><div class="two"><label class="field">Years at sea (optional)<input type="number" name="experience" min="0" max="70" step="0.5" value="${esc(p.experience)}"></label><label class="field">Country (optional)<input name="country" maxlength="70" value="${esc(p.country)}"></label></div><label class="field">About your experience (optional)<textarea name="bio" maxlength="500" placeholder="Your experience and topics you can help with…">${esc(p.bio)}</textarea></label><div class="field">Profile photo (optional)<div class="qa-profile-photo"><input id="qaProfilePhoto" type="file" accept="image/*"><button class="qa-link" type="button" id="removeProfilePhoto">Remove photo</button></div></div><p class="qa-draft-note">No employer, vessel, seafarer ID, passport, or certificate upload is required. Rank and experience are not verified. Photo changes are saved immediately in this browser.</p><button class="btn">Save profile</button><p class="qa-status" id="qaProfileStatus" role="status"></p></form><div><section class="card"><div class="eyebrow" style="font-size:9px;color:var(--teal)">YOUR CONTRIBUTION JOURNEY</div><h2 style="font-size:22px">${Object.keys(state.qaBadges).length} of ${qaBadgeDefinitions.length} milestones</h2><p class="qa-status">${m.asked} questions · ${m.answered} questions answered · ${m.outcomes} outcomes recorded</p><button class="btn quiet" data-nav="badges">Your milestones so far →</button></section><section class="card"><h3 style="margin-top:0;font-size:16px">Favorite topics</h3><p class="hint">Choose the subjects you want to find and help with.</p><div class="qa-topiclist">${equipment.slice(1).map(t=>`<button class="${state.followed.includes(t)?'active':''}" data-qa-follow="${esc(t)}">${state.followed.includes(t)?'✓ ':''}${esc(t)}</button>`).join('')}</div></section><div class="qa-helper"><strong>What is stored here?</strong><p>In this prototype, your profile, photos, questions, and answers stay in this browser. They are not shared with another account. A live release will need cloud storage and clear public/private controls.</p></div></div></div>`;document.querySelector('#qaProfileForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.name.trim())return;const old={...state.profile};state.profile={...state.profile,...d,name:d.name.trim(),rank:d.rank.trim()};if(!persist()){state.profile=old;return}render();toast('Profile saved in this browser.')};document.querySelector('#qaProfilePhoto').onchange=async e=>{const images=[];await addPhotos(e.target.files,images,1);if(images.length){const before=state.profile.photo;state.profile.photo=images[0];if(!persist()){state.profile.photo=before;return}render()}};document.querySelector('#removeProfilePhoto').onclick=()=>{const before=state.profile.photo;state.profile.photo='';if(!persist()){state.profile.photo=before;return}render()}}
ask=function(){baseAsk();const dept=document.querySelector('#askForm select[name="dept"]');if(dept){const old=dept.value;dept.innerHTML=Object.keys(topicsByDepartment).map(d=>`<option>${d}</option>`).join('');dept.value=Object.keys(topicsByDepartment).includes(old)?old:state.profile.department||'Engine'}const title=document.querySelector('.page-title');if(title)title.textContent='What would you like to ask?';const subtitle=document.querySelector('.subtitle');if(subtitle)subtitle.textContent='Engine, deck, electrical, or life at sea—give the crew enough context to help.'};
detail=function(){const q=all().find(q=>q.id===selected);if(!q){nav('learn');return}baseDetail();if(own(q)&&qProfileName()!=='JV Ursal')for(const node of app.querySelectorAll('.meta'))node.textContent=node.textContent.replace('JV Ursal',qProfileName());app.insertAdjacentHTML('beforeend',`<div class="qa-report"><button class="qa-link" id="qaReport">Report unsafe or misleading content</button><button class="qa-link" data-qa-topic="${esc(q.equipment)}">More in ${esc(q.equipment)} →</button></div><div id="qaReportArea"></div>`);document.querySelector('#qaReport').onclick=()=>{document.querySelector('#qaReportArea').innerHTML='<form class="card" id="qaReportForm"><h3 style="font-size:15px">Report this discussion</h3><p class="hint">Local prototype only. No moderator receives this yet.</p><label class="field">What should be reviewed?<textarea name="reason" required maxlength="1500"></textarea></label><button class="btn">Save local report</button></form>';document.querySelector('#qaReportForm').onsubmit=e=>{e.preventDefault();const reason=new FormData(e.target).get('reason').trim();if(!reason)return;state.reports.push({question:q.id,reason,at:new Date().toISOString()});if(!persist()){state.reports.pop();return}document.querySelector('#qaReportArea').innerHTML='<p class="qa-status">Report saved locally. It has not been sent to a moderator.</p>'}};if(lastViewedId!==q.id){state.qaVisits.push({id:q.id,topic:q.equipment,at:new Date().toISOString()});state.qaVisits=state.qaVisits.slice(-30);basePersist();lastViewedId=q.id}}
let previousQAPage='home';
render=function(){renderNav();document.querySelector('#sectionName').textContent=({home:'Your dashboard',explore:'Questions from the crew',learn:'Question & answer library',ask:'Ask the crew',profile:'Your seafarer profile',badges:'Your milestones',detail:'Question & answers'})[page]||'Your dashboard';if(page==='home')dashboard();else if(page==='explore'||page==='learn')questionLibrary();else if(page==='ask')ask();else if(page==='profile')profile();else if(page==='badges')qaBadgesView();else if(page==='detail')detail();else{page='home';dashboard()}if(page!==previousQAPage&&typeof app.animate==='function'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)app.animate([{opacity:.5,transform:'translateX(12px)'},{opacity:1,transform:'translateX(0)'}],{duration:180,easing:'ease-out'});previousQAPage=page};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.activity){qaView=b.dataset.activity;page='explore';query='';topic='All topics';qaDepartment='All departments';sort='recent';render();window.scrollTo(0,0)}if(b.dataset.qaTopic){page='learn';topic=b.dataset.qaTopic;qaDepartment=departmentFor(topic)||'All departments';qaView='all';query='';sort='recent';render();window.scrollTo(0,0)}if(b.dataset.qaDept){page='learn';qaDepartment=b.dataset.qaDept;topic='All topics';qaView='all';query='';sort='recent';render();window.scrollTo(0,0)}if(b.dataset.qaView){qaView=b.dataset.qaView;sort='recent';render()}if(b.dataset.qaFollow){const t=b.dataset.qaFollow;const before=[...state.followed];state.followed=state.followed.includes(t)?state.followed.filter(x=>x!==t):[...state.followed,t];if(!persist())state.followed=before;render()}});
if(awardQABadges().length)basePersist();
render();
